"""
Canonical source of truth for Success Stories.

Both the human-facing React pages (via /api/seo/success-stories[/{slug}]) and the
crawler-facing server-rendered HTML (/api/seo/render/success-story/{slug}) read
from here, so the data lives in exactly one place.

Each story gets a stable, unique URL slug derived from name + platform.
"""
import re


def _slugify(s: str) -> str:
    s = (s or "").lower().strip()
    s = re.sub(r"[^a-z0-9]+", "-", s)
    return s.strip("-")


