def _build():
    seen = set()
    out = []
    for s in _RAW:
        base = _slugify(f"{s['name']}-{s['platform']}")
        slug = base if base else f"story-{s['id']}"
        if slug in seen:
            slug = f"{slug}-{s['id']}"
        seen.add(slug)
        out.append({**s, "slug": slug})
    return out


STORIES = _build()
STORIES_BY_SLUG = {s["slug"]: s for s in STORIES}


def get_all():
    return STORIES


def get_by_slug(slug: str):
    return STORIES_BY_SLUG.get((slug or "").lower().strip())


def get_related(story: dict, limit: int = 4):
    """Same-category stories first, then same-platform, excluding self."""
    if not story:
        return []
    out, seen = [], {story["slug"]}
    for s in STORIES:
        if s["slug"] in seen:
            continue
        if s["category"] == story["category"]:
            out.append(s)
            seen.add(s["slug"])
    for s in STORIES:
        if len(out) >= limit:
            break
        if s["slug"] in seen:
            continue
        if s["platform"] == story["platform"]:
            out.append(s)
            seen.add(s["slug"])
    return out[:limit]
